//! Cache reads, still matching the old Option API.

use crate::api;

pub fn cached(key: &str) -> i32 {
    match api::fetch(key) {
        Some(value) => value,
        None => 0,
    }
}

//! Cache reads.

use crate::api;

pub fn cached(key: &str) -> i32 {
    match api::fetch(key) {
        Some(value) => value,
        None => 0,
    }
}

//! Cache reads.

use crate::api;

pub fn cached(key: &str) -> i32 {
    match api::fetch(key) {
        Ok(value) => value,
        Err(_) => 1,
    }
}

//! Cache reads.

use crate::api;

pub fn cached(key: &str) -> i32 {
    match api::fetch(key) {
        Ok(value) => value,
        Err(_) => 0,
    }
}

//! Cache reads.

use crate::api;

pub fn cached(key: &str) -> i32 {
    match api::fetch(key) {
        Ok(value) => value + 1,
        Err(_) => 0,
    }
}

